1	/**
2	 * T4: Draft-state comment resolution dispatch.
3	 *
4	 * When T2 reports `hasOpenComments: true` for an `in_review` task, this handler:
5	 *
6	 *   1. Claims the review work by appending a `review_started` log entry to
7	 *      the task YAML on the management-repo feature branch and pushing.
8	 *      First-push-wins: if the push is rejected, another agent claimed first.
9	 *
10	 *   2. Generates a review briefing that instructs Claude to execute the
11	 *      `respond-to-review` skill.
12	 *
13	 *   3. Invokes the Claude executor via SubProcessAdapter with that briefing.
14	 */
15	
16	import { execSync, spawnSync } from "node:child_process";
17	import { join } from "node:path";
18	import { tmpdir } from "node:os";
19	import type { Task } from "../types/task.js";
20	import type { PrStatusResult } from "../poll/check-in-review-prs.js";
21	import { buildGitCommitEnv } from "../git-env.js";
22	import { SubProcessAdapter } from "../adapter/spawn.js";
23	import type { ExecutorInput } from "@workflow/runtime-abi";
24	import { taskYamlRelPath } from "../paths.js";
25	import { readTask, writeTask } from "../utils/task-yaml-io.js";
26	import { writeBriefing } from "../briefing/write-briefing.js";
27	import { preambleSection, identitySection, taskContextSection, modelSection, joinSections } from "../briefing/briefing-template.js";
28	
29	// ── Public types ──────────────────────────────────────────────────────────────
30	
31	export type DraftReviewOutcome =
32	  | "claim_lost"
33	  | "dispatched";
34	
35	export interface DispatchOneReviewOptions {
36	  workspaceRoot: string;
37	  featureId: string;
38	  taskId: string;
39	  taskBranch: string;
40	  implRepoRoot: string;
41	  /** SSH or HTTPS URL of the implementation repo. */
42	  implRepoUrl: string;
43	  gitAuthorEmail: string;
44	  gitAuthorName?: string;
45	  sshKeyPath?: string;
46	  workflowLocalPath: string;
47	  maxTurns: number;
48	  maxTokens: number;
49	  logSinkEnabled: boolean;
50	  implementationModel: string;
51	  workspaceId: string;
52	  githubToken: string;
53	  emit: (event: Record<string, unknown>) => void;
54	}
55	
56	export interface HandleDraftReviewsOptions {
57	  prResults: PrStatusResult[];
58	  workspaceRoot: string;
59	  resolveImplRepoRoot: (repoId: string) => string;
60	  resolveImplRepoUrl: (repoId: string) => string;
61	  resolveTaskRepoId: (featureId: string, taskId: string) => string;
62	  resolveImplementationModel: (featureId: string, taskId: string) => string;
63	  gitAuthorEmail: string;
64	  gitAuthorName?: string;
65	  sshKeyPath?: string;
66	  workflowLocalPath: string;
67	  maxTurns: number;
68	  maxTokens: number;
69	  logSinkEnabled: boolean;
70	  workspaceId: string;
71	  githubToken: string;
72	  emit: (event: Record<string, unknown>) => void;
73	}
74	
75	// ── Internal helpers ──────────────────────────────────────────────────────────
76	
77	function generateReviewBriefing(opts: {
78	  taskId: string;
79	  featureId: string;
80	  taskTitle: string;
81	  taskBranch: string;
82	  taskRepo: string;
83	  taskRepoRoot: string;
84	  workspaceRoot: string;
85	  prUrl: string;
86	  gitAuthorEmail: string;
87	  gitAuthorName: string;
88	  implementationModel: string;
89	}): string {
90	  const {
91	    taskId, featureId, taskTitle, taskBranch, taskRepo, taskRepoRoot,
92	    workspaceRoot, prUrl, gitAuthorEmail, gitAuthorName, implementationModel,
93	  } = opts;
94	
95	  return joinSections(
96	    preambleSection(),
97	    identitySection({ gitAuthorEmail, gitAuthorName }),
98	    taskContextSection("Your claimed task", {
99	      taskId, featureId, taskTitle, taskBranch,
100	      taskRepo, taskRepoRoot, workspaceRoot, prUrl,
101	    }),
102	    [
103	      "## What you must do",
104	      "",
105	      "1. Run `/respond-to-review` to read and address all open PR review comments,",
106	      "   then convert the PR from draft back to ready-for-review.",
107	      "",
108	      "Complete all steps without stopping or asking for confirmation.",
109	    ],
110	    modelSection(implementationModel),
111	    [
112	      "## Rules",
113	      "",
114	      "- Do not ask clarifying questions.",
115	      "- Use `GITHUB_TOKEN` from the environment for all GitHub API calls.",
116	      "- If you are stuck and cannot proceed, stop gracefully without opening new PRs.",
117	    ],
118	  );
119	}
120	
121	// ── Public API ────────────────────────────────────────────────────────────────
122	
123	export async function dispatchOneReview(
124	  opts: DispatchOneReviewOptions,
125	): Promise<DraftReviewOutcome> {
126	  const {
127	    workspaceRoot,
128	    featureId,
129	    taskId,
130	    taskBranch,
131	    implRepoRoot,
132	    implRepoUrl,
133	    gitAuthorEmail,
134	    gitAuthorName = gitAuthorEmail,
135	    sshKeyPath,
136	    workflowLocalPath,
137	    maxTurns,
138	    maxTokens,
139	    logSinkEnabled,
140	    implementationModel,
141	    workspaceId,
142	    githubToken,
143	    emit,
144	  } = opts;
145	
146	  const env = buildGitCommitEnv(gitAuthorEmail, gitAuthorName, sshKeyPath);
147	  const now = new Date().toISOString();
148	
149	  // ── 1. Checkout and reset task branch in management repo ──────────────────────
150	  try {
151	    execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
152	    execSync(`git -C "${workspaceRoot}" checkout "${taskBranch}"`, { env, stdio: "pipe" });
153	    execSync(`git -C "${workspaceRoot}" reset --hard "origin/${taskBranch}"`, { env, stdio: "pipe" });
154	  } catch (e) {
155	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
156	    return "claim_lost";
157	  }
158	
159	  // ── 2. Read task and guard against duplicate claims ───────────────────────────
160	  let task: Task;
161	  try {
162	    task = readTask(workspaceRoot, featureId, taskId);
163	  } catch (e) {
164	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
165	    return "claim_lost";
166	  }
167	
168	  const lastEntry = task.log[task.log.length - 1];
169	  if (lastEntry?.action === "review_started") {
170	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: "last log entry is review_started" });
171	    return "claim_lost";
172	  }
173	
174	  const REVIEW_CYCLE_ACTIONS = new Set(["review_started", "comments_addressed"]);
175	  const MAX_REVIEW_CYCLES = 3;
176	  let consecutiveReviewCycles = 0;
177	  for (let i = task.log.length - 1; i >= 0; i--) {
178	    if (!REVIEW_CYCLE_ACTIONS.has(task.log[i].action)) break;
179	    if (task.log[i].action === "review_started") consecutiveReviewCycles++;
180	  }
181	  if (consecutiveReviewCycles >= MAX_REVIEW_CYCLES) {
182	    emit({ type: "review_loop_detected", task_id: taskId, feature_id: featureId });
183	    return "claim_lost";
184	  }
185	
186	  // ── 3. Write review_started log entry and push (first-push-wins) ──────────────
187	  task.log.push({ action: "review_started", by: gitAuthorEmail, at: now, note: "Review dispatch claimed." });
188	  task.execution.last_updated_by = gitAuthorEmail;
189	  task.execution.last_updated_at = now;
190	  writeTask(workspaceRoot, featureId, task);
191	
192	  const relPath = taskYamlRelPath(featureId, taskId);
193	  try {
194	    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
195	    execSync(`git -C "${workspaceRoot}" commit -m "chore(${taskId}): review_started — claim"`, { env, stdio: "pipe" });
196	  } catch (e) {
197	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
198	    return "claim_lost";
199	  }
200	
201	  const claimPush = spawnSync("git", ["-C", workspaceRoot, "push", "origin", taskBranch], {
202	    env, encoding: "utf-8",
203	  });
204	  if (claimPush.status !== 0) {
205	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: claimPush.stderr });
206	    return "claim_lost";
207	  }
208	
209	  emit({ type: "review_dispatching", task_id: taskId, feature_id: featureId, pr_url: task.pr.url });
210	
211	  // ── 4. Build review briefing and run executor ─────────────────────────────────
212	  const reviewBriefing = generateReviewBriefing({
213	    taskId,
214	    featureId,
215	    taskTitle: task.title,
216	    taskBranch,
217	    taskRepo: task.repo,
218	    taskRepoRoot: implRepoRoot,
219	    workspaceRoot,
220	    prUrl: task.pr.url,
221	    gitAuthorEmail,
222	    gitAuthorName,
223	    implementationModel,
224	  });
225	
226	  const { briefingPath } = writeBriefing({ taskId, briefingContent: reviewBriefing });
227	
228	  const resultPath = join(tmpdir(), `review-result-${taskId}.json`);
229	
230	  const input: ExecutorInput = {
231	    taskId,
232	    featureId,
233	    workspaceId,
234	    taskRepoUrl: implRepoUrl,
235	    taskRepoBranch: taskBranch,
236	    taskRepoPath: implRepoRoot,
237	    briefingPath,
238	    resultPath,
239	    budgetTokens: maxTokens,
240	    sshKeyPath: sshKeyPath ?? "",
241	    githubToken,
242	  };
243	
244	  const reviewAdapter = new SubProcessAdapter({
245	    extraEnv: {
246	      WORKSPACE_ROOT: workspaceRoot,
247	      TASK_BRANCH: taskBranch,
248	      GIT_AUTHOR_EMAIL: gitAuthorEmail,
249	      GIT_AUTHOR_NAME: gitAuthorName,
250	      WORKFLOW_LOCAL_PATH: workflowLocalPath,
251	      MAX_TURNS: String(maxTurns),
252	      LOG_SINK_ENABLED: logSinkEnabled ? "1" : "0",
253	    },
254	  });
255	
256	  const runResult = await reviewAdapter.run(input);
257	
258	  emit({
259	    type: "review_dispatch_complete",
260	    task_id: taskId,
261	    feature_id: featureId,
262	    outcome: runResult.terminal_status,
263	  });
264	
265	  return "dispatched";
266	}
267	
268	export async function handleDraftReviews(
269	  opts: HandleDraftReviewsOptions,
270	): Promise<void> {
271	  const {
272	    prResults,
273	    workspaceRoot,
274	    resolveImplRepoRoot,
275	    resolveImplRepoUrl,
276	    resolveTaskRepoId,
277	    resolveImplementationModel,
278	    gitAuthorEmail,
279	    gitAuthorName,
280	    sshKeyPath,
281	    workflowLocalPath,
282	    maxTurns,
283	    maxTokens,
284	    logSinkEnabled,
285	    workspaceId,
286	    githubToken,
287	    emit,
288	  } = opts;
289	
290	  const draftTasks = prResults.filter((r) => r.hasOpenComments === true);
291	
292	  for (const result of draftTasks) {
293	    const { taskId, featureId } = result;
294	
295	    let repoId: string;
296	    try {
297	      repoId = resolveTaskRepoId(featureId, taskId);
298	    } catch (e) {
299	      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
300	      continue;
301	    }
302	
303	    let implRepoRoot: string;
304	    let implRepoUrl: string;
305	    try {
306	      implRepoRoot = resolveImplRepoRoot(repoId);
307	      implRepoUrl = resolveImplRepoUrl(repoId);
308	    } catch (e) {
309	      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
310	      continue;
311	    }
312	
313	    let implementationModel: string;
314	    try {
315	      implementationModel = resolveImplementationModel(featureId, taskId);
316	    } catch (e) {
317	      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
318	      continue;
319	    }
320	
321	    const taskBranch = `feature/${featureId}-${taskId}`;
322	
323	    try {
324	      await dispatchOneReview({
325	        workspaceRoot,
326	        featureId,
327	        taskId,
328	        taskBranch,
329	        implRepoRoot,
330	        implRepoUrl,
331	        gitAuthorEmail,
332	        gitAuthorName,
333	        sshKeyPath,
334	        workflowLocalPath,
335	        maxTurns,
336	        maxTokens,
337	        logSinkEnabled,
338	        implementationModel,
339	        workspaceId,
340	        githubToken,
341	        emit,
342	      });
343	    } catch (e) {
344	      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
345	    }
346	  }
347	}
